{
  "hypotheses": [
    {
      "table": "fda_snapshot.recalls",
      "column": "openfda_product_ndc",
      "transform": "identity",
      "rationale": "The openfda_product_ndc column in the recalls table directly stores the 11-digit NDC product code, matching the hospital's item_master.ndc11 format exactly."
    },
    {
      "table": "fda_snapshot.shortages",
      "column": "package_ndc",
      "transform": "strip_hyphens",
      "rationale": "Package NDCs appear as 5-4-2 segments (e.g., \"0009-0225-02\"). Removing hyphens via strip_hyphens produces the 11-digit product code format used by the hospital."
    },
    {
      "table": "fda_snapshot.ndc_packages",
      "column": "product_ndc",
      "transform": "lpad_11",
      "rationale": "Product NDCs are stored as 4-3 segments (e.g., \"82953-020\"). Applying lpad_11 left-pads the segment to 11 digits, converting it to the hospital's ndc11 format."
    },
    {
      "table": "wholesaler.catalog",
      "column": "ndc",
      "transform": "lpad_11",
      "rationale": "Wholesaler NDCs are 8 or 9 digits without separators (e.g., \"143926901\"). The lpad_11 transform left-pads with zeros to reach exactly 11 digits, aligning with the hospital's format."
    }
  ]
}

